import { SchedulePicker } from '@refy-design/web';
import type { ComponentProps } from 'react';
const july23 = new Date(2026, 6, 23);
const selected = {
  '2026-07-23': ['09:00', '09:30', '10:00', '10:30'],
  '2026-07-24': ['08:00', '08:30', '15:00', '15:30'],
};
export function Example() {
  const args: Pick<
    ComponentProps<typeof SchedulePicker>,
    'defaultActiveDate' | 'minDate' | 'maxDate' | 'defaultValue'
  > = {
    defaultActiveDate: july23,
    minDate: new Date(2026, 6, 21),
    maxDate: new Date(2026, 7, 31),
    defaultValue: selected,
  };
  return <SchedulePicker {...args} />;
}

